```json
{
    "predictors": [
        {
            "name": "Earnings Forecast Dispersion",
            "construction": "Standard deviation of analysts' earnings forecasts for the next fiscal year, divided by the absolute value of the mean forecast.",
            "rationale": "Higher dispersion in earnings forecasts indicates greater uncertainty about a firm's future, potentially leading to higher risk premiums.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Dividend Yield Momentum",
            "construction": "The change in dividend yield over the past 12 months, calculated as the current dividend yield minus the dividend yield 12 months ago.",
            "rationale": "An increasing dividend yield trend may signal improving financial health and investor appeal.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Growth Rate",
            "construction": "The annual growth rate in the number of employees as reported in annual reports.",
            "rationale": "Firms expanding their workforce may anticipate future growth opportunities and demand.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Trading Ratio",
            "construction": "The ratio of insider purchases to insider sales over the past 6 months.",
            "rationale": "Significant insider buying relative to selling may suggest management's confidence in the firm's future prospects.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Patent Citation Impact",
            "construction": "The number of citations received by a firm's patents over the past 3 years, scaled by the total number of patents.",
            "rationale": "Highly cited patents may indicate more valuable intellectual property and potential competitive advantages.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration",
            "construction": "The proportion of a firm's revenue attributable to its top five customers, as disclosed in annual reports.",
            "rationale": "Lower customer concentration suggests diversified revenue streams and reduced dependency risk.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Advertising Efficiency",
            "construction": "Ratio of sales growth to advertising expenditure growth over the past year.",
            "rationale": "A higher ratio indicates more effective conversion of advertising spend into sales, reflecting potential operational efficiency.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Capital Investment Gap",
            "construction": "The difference between the firm's actual capital expenditures and the industry average over the past year, scaled by total assets.",
            "rationale": "Underinvestment relative to peers may imply future growth opportunities not yet realized.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "R&D Volatility",
            "construction": "Standard deviation of research and development expenditures over the past 5 years, divided by the mean R&D expenditure.",
            "rationale": "Firms with stable R&D investments may indicate consistent innovation strategies and lower operational risk.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Supply Chain Integration",
            "construction": "The number of strategic partnerships or joint ventures in the supply chain, as reported in press releases and annual reports.",
            "rationale": "Better integrated supply chains can enhance operational efficiency and reduce costs, potentially leading to higher profitability.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
```
